DECLARE @json NVARCHAR(MAX) = N'@{replace(string(activity('Get Workspace Dataflows').output.value), '''', '''''')}';
DECLARE @wsId NVARCHAR(100) = '@{item().id}';
IF @json IS NOT NULL AND LEN(@json) > 2
BEGIN
    INSERT INTO [dbo].[dataflows] (workspace_id, id, displayName, type, loaded_at)
    SELECT @wsId, id, displayName, type, GETDATE()
    FROM OPENJSON(@json)
    WITH (
        id          NVARCHAR(100) '$.id',
        displayName NVARCHAR(255) '$.displayName',
        type        NVARCHAR(50)  '$.type'
    );
END

